local function _dvstvihhirk(s,cnt)local o={}for i=0,cnt-1 do local p=i*4+1 o[i+1]=byte(s,p)+byte(s,p+1)*256+byte(s,p+2)*65536+byte(s,p+3)*16777216 end return o end local function _ojntlm(w)local o={}for i=1,#w do local v=w[i]o[i]=char(v%256,rs(v,8)%256,rs(v,16)%256,rs(v,24)%256)end return concat(o)end
